CREATE TABLE service_categories(id uuid PRIMARY KEY,code varchar(40) NOT NULL UNIQUE,name varchar(100) NOT NULL,default_duration_minutes integer NOT NULL CHECK(default_duration_minutes BETWEEN 15 AND 480));
INSERT INTO service_categories VALUES('00000000-0000-0000-0000-000000000401','GENERAL','General service',60),('00000000-0000-0000-0000-000000000402','INSPECTION','Vehicle inspection',45),('00000000-0000-0000-0000-000000000403','REPAIR','Repair visit',120);
CREATE TABLE appointments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid NOT NULL,service_category_id uuid NOT NULL REFERENCES service_categories(id),requested_start_time timestamptz NOT NULL,expected_end_time timestamptz NOT NULL,estimated_duration_minutes integer NOT NULL CHECK(estimated_duration_minutes BETWEEN 15 AND 480),customer_complaint varchar(2000) NOT NULL,appointment_status varchar(24) NOT NULL CHECK(appointment_status IN ('REQUESTED','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','NO_SHOW')),booking_source varchar(16) NOT NULL CHECK(booking_source IN ('STAFF','PHONE','WALK_IN')),assigned_technician_id uuid,registration varchar(32) NOT NULL,vehicle_model varchar(180) NOT NULL,customer_name varchar(120) NOT NULL,branch_timezone varchar(80) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,check_in_state varchar(24),check_in_key varchar(100),check_in_request jsonb,check_in_id uuid,work_order_id uuid,last_error_status integer,UNIQUE(tenant_id,id),CHECK(expected_end_time>requested_start_time));
CREATE TABLE appointment_capacity_reservations(appointment_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,technician_id uuid,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),CHECK(ends_at>starts_at));
CREATE INDEX booking_capacity ON appointment_capacity_reservations(tenant_id,branch_id,starts_at,ends_at) WHERE active;
CREATE INDEX booking_technician ON appointment_capacity_reservations(tenant_id,technician_id,starts_at,ends_at) WHERE active AND technician_id IS NOT NULL;
CREATE INDEX booking_directory ON appointments(tenant_id,branch_id,requested_start_time,id);
CREATE TABLE branch_schedule_snapshots(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,appointment_id uuid NOT NULL REFERENCES appointments(id),configuration jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appointment_status_history(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,appointment_id uuid NOT NULL,from_status varchar(24),to_status varchar(24) NOT NULL,note varchar(1000) NOT NULL,actor_id uuid NOT NULL,correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id));
CREATE TABLE operation_keys(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,request_key varchar(100) NOT NULL,operation varchar(100) NOT NULL,request_hash varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor_id,request_key,operation));
